import{_ as e}from"./chunks/Audio.COine8Wh.js";import{_ as s}from"./chunks/Tags.BJ536pW3.js";import{c as n,o,j as t,G as i,ae as l,a as r}from"./chunks/framework.Bw0Gm4PQ.js";const p=JSON.parse('{"title":"Alaska’s Right to Ivory Sales and Tradition Act","description":"","frontmatter":{"legisId":"2026-06-12-alaskas-right-to-ivory-sales-and-tradition-act","title":"Alaska’s Right to Ivory Sales and Tradition Act","displayTitle":"Alaska’s Right to Ivory Sales and Tradition Act","lawNumber":"119-99","billNumber":"S. 254","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ99.xml","publishDate":"2026-06-12T00:00:00-05:00","industries":["trade","environment"],"agencies":[],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Alaska’s Right to Ivory Sales and Tradition Act\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2026-06-12-alaskas-right-to-ivory-sales-and-tradition-act\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Alaska’s Right to Ivory Sales and Tradition Act\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2026-06-12-alaskas-right-to-ivory-sales-and-tradition-act\\",\\"datePublished\\":\\"2026-06-12T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2026-06-12-alaskas-right-to-ivory-sales-and-tradition-act\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2026-06-12-alaskas-right-to-ivory-sales-and-tradition-act.md","filePath":"congress-bills/2026-06-12-alaskas-right-to-ivory-sales-and-tradition-act.md","lastUpdated":1788887623000}'),d={name:"congress-bills/2026-06-12-alaskas-right-to-ivory-sales-and-tradition-act.md"},b=Object.assign(d,{setup(c){return(g,a)=>(o(),n("div",null,[a[0]||(a[0]=t("h1",{id:"alaska-s-right-to-ivory-sales-and-tradition-act",tabindex:"-1"},[r("Alaska’s Right to Ivory Sales and Tradition Act "),t("a",{class:"header-anchor",href:"#alaska-s-right-to-ivory-sales-and-tradition-act","aria-label":'Permalink to "Alaska’s Right to Ivory Sales and Tradition Act"'},"​")],-1)),i(e),i(s,{list:"/congress-bills"}),a[1]||(a[1]=l('<p>Signed into law on Friday, June 12, 2026. Public Law 119-99, S. 254.</p><p><strong>Headline:</strong> The ARTIST Act protects qualifying Alaska Natives’ subsistence use of marine mammals and interstate sales of authentic traditional goods.</p><p><strong>Why it matters:</strong> The law preserves Alaska Native cultural and economic practices while retaining federal authority to protect depleted marine mammal species or stocks.</p><p><strong>What the law does:</strong></p><ul><li>Allows qualifying Alaska Natives to take marine mammals without waste for subsistence or to make and sell authentic handicrafts and clothing.</li><li>Protects interstate sales of qualifying Alaska Native products containing marine mammal ivory, bone, or baleen.</li><li>Bars states from banning protected transactions involving those authentic Alaska Native products.</li><li>Limits authenticity protections to goods made with significant natural materials, traditional methods, and no mass copying.</li><li>Requires challenged federal restrictions involving depleted species or stocks to be supported publicly in writing by substantial evidence, including consideration of Indigenous knowledge.</li><li>Preserves existing tribal rights and government-to-government consultation and engagement.</li></ul><p><strong>Who it affects:</strong></p><ul><li>Qualifying Alaska Native subsistence users, artists, craftspeople, and sellers.</li><li>Buyers and interstate sellers of authentic Alaska Native handicrafts and clothing.</li><li>States regulating products made with marine mammal ivory, bone, or baleen.</li><li>Alaska Native organizations challenging federal restrictions involving depleted marine mammals.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>Buyers may purchase qualifying authentic Alaska Native goods across state lines despite conflicting state bans.</li><li>Products marketed as authentic must meet the law’s material, maker, method, and non-mass-copying standards.</li></ul><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="alaska-s-right-to-ivory-sales-and-tradition-act-1" tabindex="-1">Alaska’s Right to Ivory Sales and Tradition Act <a class="header-anchor" href="#alaska-s-right-to-ivory-sales-and-tradition-act-1" aria-label="Permalink to &quot;Alaska’s Right to Ivory Sales and Tradition Act&quot;">​</a></h3><p>The ARTIST Act protects qualifying Alaska Natives’ ability to take marine mammals without waste for subsistence and for making and selling authentic traditional handicrafts and clothing. It also protects interstate trade in qualifying Alaska Native products made with marine mammal ivory, bone, or baleen, while allowing federal restrictions when a marine mammal species or stock is depleted.</p><p><strong>Key takeaways:</strong></p><ul><li>Authentic Alaska Native handicrafts and clothing must use natural materials to a significant extent, be made by a qualifying Alaska Native using traditional methods, and not be mass-copied.</li><li>Marine mammals may be taken by qualifying Alaska Natives for subsistence or to create and sell authentic handicrafts and clothing, as long as the taking is not wasteful.</li><li>Items marketed as authentic Alaska Native handicrafts and clothing may be sold across state lines only if they meet the Act’s definition.</li><li>States may not ban protected transactions involving marine mammal ivory, bone, or baleen incorporated by an Alaska Native into authentic Alaska Native handicrafts or clothing.</li><li>The federal government may regulate Alaska Native taking of a depleted marine mammal species or stock, but covered decisions must be publicly supported in writing by substantial evidence, including consideration of Indigenous knowledge, when challenged by an Alaska Native organization.</li><li>The Act does not change existing tribal rights or weaken government-to-government consultation or engagement.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ99.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ99.xml</a></p>',15))]))}});export{p as __pageData,b as default};
